// D4-05: the README's documents benchmark numbers ARE docs/benchmarks/documents.csv's. The block between
// the docs-bench markers is regenerated by scripts/bench-docs-readme.mjs and this test recomputes it and
// demands equality; the CSV itself must carry measured rows only, with provenance and the 8 GB column.
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
import { describe, expect, it } from 'vitest';
import {
  BEGIN,
  COLUMNS,
  EIGHT_GB,
  END,
  OPERATIONS,
  parseCsv,
  renderDocsBench,
  summarise,
} from '../scripts/bench-docs-csv.mjs';

const root = join(import.meta.dirname, '..');
const readme = readFileSync(join(root, 'README.md'), 'utf8');
const csvText = readFileSync(join(root, 'docs', 'benchmarks', 'documents.csv'), 'utf8');
const rows = parseCsv(csvText);

function block(): string {
  const a = readme.indexOf(BEGIN);
  const b = readme.indexOf(END);
  expect(a, 'README has the docs-bench:begin marker').toBeGreaterThanOrEqual(0);
  expect(b, 'README has the docs-bench:end marker').toBeGreaterThan(a);
  return readme.slice(a + BEGIN.length, b).trim();
}

describe('docs/benchmarks/documents.csv', () => {
  it('has the documented header and rows', () => {
    expect(csvText.split('\n')[0]).toBe(COLUMNS.join(','));
    expect(rows.length).toBeGreaterThan(0);
  });

  it('every row has generated provenance, the command, the 8 GB wording and matched the naive reference', () => {
    for (const r of rows) {
      const where = `${r['driver']} ${r['operation']} run ${r['run']}`;
      expect(r['match'], where).toBe('true');
      expect(r['precise_memory'], where).toBe('true');
      expect(r['eight_gb'], where).toBe(EIGHT_GB);
      expect(r['command'], where).toBe('npm run bench:documents');
      expect(r['commit'], where).toMatch(/^[0-9a-f]{7,40}(-dirty)?$/);
      expect(r['machine'], where).toMatch(/^.+, \d+ GB$/);
      expect(r['chrome'], where).toMatch(/^Chrome\/\d/);
      expect(r['date_utc'], where).toMatch(/^\d{4}-\d\d-\d\dT/);
      expect([r['docs'], r['chunks_per_doc'], r['dim'], r['chunk_text_bytes']], where).toEqual([
        '100',
        '200',
        '384',
        '400',
      ]);
      expect(OPERATIONS, where).toContain(r['operation']);
      expect(Number(r['js_heap_peak_bytes']), `${where}: JS heap peak`).toBeGreaterThan(0);
      for (const c of ['ops', 'total_ms', 'per_op_ms', 'p50_ms', 'p95_ms'])
        expect(Number(r[c]), `${where}: ${c}`).toBeGreaterThan(0);
    }
    expect(new Set(rows.map((r) => r['commit'])).size, 'one commit value per run').toBe(1);
  });

  it('covers put, warm and cold query, delete and clear on OPFS and IndexedDB: 3 runs each, and a restart run', () => {
    for (const driver of ['opfs', 'indexeddb']) {
      for (const op of OPERATIONS) {
        const g = rows.filter((r) => r['driver'] === driver && r['operation'] === op);
        expect(g.filter((r) => r['restart'] === 'false').length, `${driver} ${op}`).toBe(3);
      }
      const restart = rows.filter(
        (r) => r['driver'] === driver && r['operation'] === 'query_cold' && r['restart'] === 'true',
      );
      expect(restart.length, `${driver} restart run`).toBe(1);
    }
  });

  it('every clear row found nothing behind and every put row stored 100 documents', () => {
    for (const r of rows.filter((x) => x['operation'] === 'clear')) expect(r['match']).toBe('true');
    for (const r of rows.filter((x) => x['operation'] === 'put')) expect(r['ops']).toBe('100');
  });
});

describe('README documents benchmark', () => {
  it('the generated block equals what the CSV renders to (numbers come from the CSV only)', () => {
    expect(block()).toBe(renderDocsBench(rows).trim());
  });

  it('says "not measured on 8 GB" in the block and in every table row, names the machine and the command', () => {
    const b = block();
    expect(b).toContain('Apple M5 Pro, 48 GB');
    expect(b).toContain('not measured on 8 GB');
    expect(b).toContain('`npm run bench:documents`');
    const lines = b
      .split('\n')
      .filter((l) => l.startsWith('| ') && !l.startsWith('| ---') && !l.startsWith('| Operation'));
    expect(lines.length).toBe(summarise(rows).length);
    for (const l of lines) expect(l.trimEnd().endsWith(`| ${EIGHT_GB} |`)).toBe(true);
  });

  it('names its figures: the JS heap peak is called that, and is not called memory use', () => {
    const b = block();
    expect(b).toContain('JS heap peak');
    expect(b).toMatch(/not process memory/);
    expect(b.toLowerCase()).not.toContain('peak memory');
  });

  it('claims nothing the CSV does not show: no inference, cost or compliance wording', () => {
    const b = block().toLowerCase();
    for (const bad of [
      'inference',
      'tokens per second',
      'rupee',
      'saving',
      'complian',
      'dpdp',
      'rbi',
    ])
      expect(b, bad).not.toContain(bad);
  });
});
